-- M1 第二块 PR3：预算与配额、站内提醒。
-- Create "budgets" table
CREATE TABLE "budgets" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "org_id" bigint NOT NULL, "scope" character varying NOT NULL, "scope_id" bigint NOT NULL DEFAULT 0, "period" character varying NOT NULL, "metric" character varying NOT NULL, "limit_value" bigint NOT NULL, "threshold_pct" bigint NOT NULL DEFAULT 80, "action" character varying NOT NULL DEFAULT 'block', "enabled" boolean NOT NULL DEFAULT true, "note" character varying NOT NULL DEFAULT '', "created_by" bigint NOT NULL, PRIMARY KEY ("id"));
-- Create index "budget_org_id_scope_scope_id_period_metric" to table: "budgets"
CREATE UNIQUE INDEX "budget_org_id_scope_scope_id_period_metric" ON "budgets" ("org_id", "scope", "scope_id", "period", "metric");
-- Create "notifications" table
CREATE TABLE "notifications" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "org_id" bigint NOT NULL, "user_id" bigint NOT NULL, "kind" character varying NOT NULL, "title" character varying NOT NULL, "detail" jsonb NULL, "dedupe_key" character varying NOT NULL, "read_at" timestamptz NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "notification_user_id_dedupe_key" to table: "notifications"
CREATE UNIQUE INDEX "notification_user_id_dedupe_key" ON "notifications" ("user_id", "dedupe_key");
-- Create index "notification_user_id_created_at" to table: "notifications"
CREATE INDEX "notification_user_id_created_at" ON "notifications" ("user_id", "created_at");
